import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

def dep(value: str = "default"):
    return value

@app.get("/")
def root(v = Depends(functools.partial(dep, value="partial"))):
    return {"v": v}

client = TestClient(app)

def test_partial():
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"v": "partial"}

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

